import React from "react";

function Dashboard() {
  return (
    <div>
      <h2>Welcome to Dashboard 🎉</h2>
      <button onClick={() => {
        localStorage.removeItem("token");
        window.location.href = "/";
      }}>
        Logout
      </button>
    </div>
  );
}

export default Dashboard;
